                        inputField.characterLimit = 1;
                        inputField.onEndEdit.AddListener(delegate { OnFieldEndEdit(inputField.text, inputFields.IndexOf(inputField)); });
                        inputFields.Add(inputField);
                        correctChars.Add(c.ToString());

                        // Position the input field
                        RectTransform inputFieldRect = inputField.GetComponent<RectTransform>();
                        inputFieldRect.anchoredPosition = new Vector2(currentXPosition, 0f);
                        currentXPosition += inputFieldRect.rect.width + characterSpacing;
                    }
                    else
                    {
                        // Instantiate text prefab for existing character
                        GameObject textGO = Instantiate(textPrefab, inputFieldParent);
                        instantiatedObjects.Add(textGO); // Track the instantiated GameObject
                        TextMeshProUGUI textComponent = textGO.GetComponent<TextMeshProUGUI>();
                        if (textComponent == null)
                        {
                            Debug.LogError("TextMeshProUGUI component is missing on textPrefab.");
                            continue;
                        }
                        textComponent.text = c.ToString();

                        // Position the text element
                        RectTransform textRect = textComponent.GetComponent<RectTransform>();
                        textRect.anchoredPosition = new Vector2(currentXPosition, 0f);
                        currentXPosition += textRect.rect.width + characterSpacing;
                    }
                }
            }
        }

